    /*
     * Deleting tbl_staff
     */
    function remove($id)
    {
        $tbl_staff = $this->Tbl_staff_model->get_tbl_staff($id);
        $data['error'] = '';
        // check if the tbl_staff exists before trying to delete it
        if(isset($tbl_staff['id']))
        {
            $this->Tbl_staff_model->delete_tbl_staff($id);
            $data['tbl_staff'] = $this->Tbl_staff_model->get_all_tbl_staff();
            $data['_view'] = 'tbl_staff/add';
            $this->load->view('layouts/main',$data);
        }
        else
            show_error('The tbl_staff you are trying to delete does not exist.');
    }
    
